/*
 * A106583  Irregular triangle read by rows generated by the morphism 1->2,
 *          2->135, 3->2, 4->5, 5->246, 6->5 starting from a(0)=1.
 * https://oeis.org/A106583
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   not stated
 * Range:     u8 n <= 9636, u16 n <= 9636, u32 n <= 9636, u64 n <= 9636,
 *            u128 n <= 9636, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A106583: irregular triangle read by rows generated by the
   morphism 1->2, 2->135, 3->2, 4->5, 5->246, 6->5, starting from a(0)=1.
   The function builds the sequence lazily and caches it for subsequent
   calls. */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* Static memoization state */
static seq_t *seq_buf     = NULL;   /* flattened sequence */
static idx_t  seq_len     = 0;      /* number of elements stored */
static idx_t  last_row_len= 0;      /* length of the most recently generated row */
static bool   initialized = false;

/* Length of the image of each symbol under the morphism */
static const idx_t map_len[7] = {0, 1, 3, 1, 1, 3, 1};

/* Append the next row produced from the current last row */
static void grow_sequence(void)
{
    /* Compute length of the previous row */
    idx_t prev_start = seq_len - last_row_len;

    /* Determine the length of the new row */
    idx_t new_row_len = 0;
    for (idx_t i = prev_start; i < seq_len; ++i)
    {
        uint64_t d = (uint64_t)seq_buf[i];
        new_row_len += map_len[d];
    }

    /* Allocate temporary buffer for the new row */
    seq_t *new_row = (seq_t*)malloc((size_t)new_row_len * sizeof(seq_t));
    if (new_row == NULL) return; /* allocation failure; caller will handle error */

    /* Build the new row element by element */
    idx_t pos = 0;
    for (idx_t i = prev_start; i < seq_len; ++i)
    {
        uint64_t d = (uint64_t)seq_buf[i];
        switch (d)
        {
            case 1:
                new_row[pos++] = (seq_t)2;
                break;
            case 2:
                new_row[pos++] = (seq_t)1;
                new_row[pos++] = (seq_t)3;
                new_row[pos++] = (seq_t)5;
                break;
            case 3:
                new_row[pos++] = (seq_t)2;
                break;
            case 4:
                new_row[pos++] = (seq_t)5;
                break;
            case 5:
                new_row[pos++] = (seq_t)2;
                new_row[pos++] = (seq_t)4;
                new_row[pos++] = (seq_t)6;
                break;
            case 6:
                new_row[pos++] = (seq_t)5;
                break;
            default:
                /* the morphism is defined only for 1..6; this case should
                   never occur for valid indices of the sequence. */
                break;
        }
    }

    /* Extend the global buffer */
    seq_t *new_buf = (seq_t*)realloc(seq_buf, (size_t)(seq_len + new_row_len) * sizeof(seq_t));
    if (new_buf == NULL)
    {
        free(new_row);
        return; /* allocation failure */
    }
    seq_buf = new_buf;

    /* Copy the new row into the buffer */
    for (idx_t i = 0; i < new_row_len; ++i)
        seq_buf[seq_len + i] = new_row[i];

    free(new_row);

    /* Update bookkeeping */
    seq_len      += new_row_len;
    last_row_len  = new_row_len;
}

/* Public interface: return a(n) for any n >= 0 */
seq_t a(idx_t n)
{
    /* One‑time initialization */
    if (!initialized)
    {
        seq_buf = (seq_t*)malloc(sizeof(seq_t));
        if (seq_buf == NULL) return (seq_t)0; /* allocation failure */
        seq_buf[0] = (seq_t)1;      /* a(0) = 1 */
        seq_len     = 1;
        last_row_len= 1;
        initialized = true;
    }

    /* Grow sequence until it covers index n */
    while (seq_len <= n)
        grow_sequence();

    return seq_buf[n];
}
